mapper.select:
SELECT d.id, dt.name AS name, dt.description AS description, dt.short_description AS shortDescription, d.latitude, d.longitude, d.season, d.user_id AS userID, d.region_id AS regionId, ( SELECT image_url FROM destination_images WHERE destination_id = d.id AND is_main = 1 LIMIT 1 ) AS thumbnailPath, cc.region_name AS regionName FROM destinations d JOIN destination_translations dt ON d.id = dt.destination_id AND dt.language_code = 'ko' JOIN country_categories cc ON d.region_id = cc.id WHERE d.region_id IN
#{id}
AND dt.name LIKE CONCAT('%', #{keyword}, '%')
AND dt.name REGEXP #{chosungPattern}

